create or replace function public.walker_request_handover(p_booking_id uuid,p_reason text,p_latitude double precision,p_longitude double precision,p_evidence_path text default null) returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid; begin if auth.uid() is null or not exists(select 1 from public.walkers where id=auth.uid() and is_active and verification_status='approved') then raise exception 'Approved active walker required'; end if; if p_latitude is null or p_longitude is null or p_latitude not between -90 and 90 or p_longitude not between -180 and 180 then raise exception 'Valid GPS coordinates required'; end if; if nullif(btrim(p_reason),'') is null or length(p_reason)>1000 then raise exception 'A handover reason is required'; end if; if not exists(select 1 from public.bookings where id=p_booking_id and walker_id=auth.uid() and status in ('accepted','arrived','in_progress')) then raise exception 'Booking is not an active duty assigned to you'; end if; if exists(select 1 from public.handover_requests where booking_id=p_booking_id and customer_decision='yes' and admin_decision='pending') then raise exception 'A handover request is already awaiting Admin review'; end if; insert into public.handover_requests(booking_id,walker_id,reason,latitude,longitude,evidence_path) values(p_booking_id,auth.uid(),btrim(p_reason),p_latitude,p_longitude,nullif(btrim(p_evidence_path),'')) returning id into v_id; insert into public.walk_events(booking_id,actor_id,event_type,note) values(p_booking_id,auth.uid(),'handover_requested','Outside handover requested; awaiting customer YES and Admin approval'); return v_id; end $$;
create or replace function public.customer_decide_handover(p_request_id uuid,p_accept boolean) returns void language plpgsql security definer set search_path='' as $$ declare v_booking uuid; begin select h.booking_id into v_booking from public.handover_requests h join public.bookings b on b.id=h.booking_id where h.id=p_request_id and b.customer_id=auth.uid() and h.customer_decision='pending' for update of h; if not found then raise exception 'Pending handover request not found for this customer'; end if; update public.handover_requests set customer_decision=case when p_accept then 'yes' else 'no' end where id=p_request_id and customer_decision='pending'; insert into public.walk_events(booking_id,actor_id,event_type,note) values(v_booking,auth.uid(),'handover_customer_decision',case when p_accept then 'Customer consented YES; Admin approval still required' else 'Customer declined handover' end); end $$;
create or replace function public.admin_review_handover(p_request_id uuid,p_approve boolean) returns void language plpgsql security definer set search_path='' as $$ declare v_booking uuid; v_customer text; begin if not private.is_admin() then raise exception 'Admin access required'; end if; select booking_id,customer_decision into v_booking,v_customer from public.handover_requests where id=p_request_id and admin_decision='pending' for update; if not found then raise exception 'Pending handover request not found'; end if; if p_approve and v_customer<>'yes' then raise exception 'Customer YES is mandatory before Admin approval'; end if; update public.handover_requests set admin_decision=case when p_approve then 'approved' else 'rejected' end,reviewed_by=auth.uid(),reviewed_at=now() where id=p_request_id; insert into public.walk_events(booking_id,actor_id,event_type,note) values(v_booking,auth.uid(),'handover_admin_decision',case when p_approve then 'Admin approved after customer YES' else 'Admin rejected handover' end); end $$;
create or replace function public.report_walk_incident(p_booking_id uuid,p_category text,p_description text) returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid; begin if auth.uid() is null then raise exception 'Authentication required'; end if; if length(btrim(coalesce(p_category,'')))<2 or length(p_category)>80 then raise exception 'Valid incident category required'; end if; if length(btrim(coalesce(p_description,'')))<5 or length(p_description)>3000 then raise exception 'Incident description must be 5–3000 characters'; end if; if not exists(select 1 from public.bookings b where b.id=p_booking_id and (b.customer_id=auth.uid() or b.walker_id=auth.uid() or private.is_admin())) then raise exception 'Booking not found for this account'; end if; insert into public.incidents(booking_id,reported_by,category,description) values(p_booking_id,auth.uid(),btrim(p_category),btrim(p_description)) returning id into v_id; insert into public.walk_events(booking_id,actor_id,event_type,note) values(p_booking_id,auth.uid(),'incident_reported','Incident submitted: '||btrim(p_category)); update public.bookings set status='incident',updated_at=now() where id=p_booking_id and status in ('assigned','accepted','arrived','in_progress','end_pending'); return v_id; end $$;
create or replace function public.admin_resolve_incident(p_incident_id uuid,p_resolution text) returns void language plpgsql security definer set search_path='' as $$ begin if not private.is_admin() then raise exception 'Admin access required'; end if; if length(btrim(coalesce(p_resolution,'')))<5 or length(p_resolution)>3000 then raise exception 'Resolution must be 5–3000 characters'; end if; update public.incidents set status='resolved',resolution=btrim(p_resolution),resolved_at=now() where id=p_incident_id and status in ('open','investigating'); if not found then raise exception 'Open incident not found'; end if; end $$;
create or replace function public.admin_create_walker_payout(p_walker_id uuid,p_period_start date,p_period_end date,p_amount_inr integer) returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid; begin if not private.is_admin() then raise exception 'Admin access required'; end if; if p_period_end<p_period_start or p_amount_inr<0 then raise exception 'Invalid payout period or amount'; end if; if not exists(select 1 from public.walkers where id=p_walker_id) then raise exception 'Walker not found'; end if; if not exists(select 1 from public.bookings where walker_id=p_walker_id and status='completed' and verified_at::date between p_period_start and p_period_end) then raise exception 'No verified completed walks in this payout period'; end if; insert into public.walker_payouts(walker_id,period_start,period_end,amount_inr,status) values(p_walker_id,p_period_start,p_period_end,p_amount_inr,'draft') returning id into v_id; return v_id; end $$;
create or replace function public.admin_approve_walker_payout(p_payout_id uuid) returns void language plpgsql security definer set search_path='' as $$ begin if not private.is_admin() then raise exception 'Admin access required'; end if; update public.walker_payouts set status='approved',approved_by=auth.uid() where id=p_payout_id and status='draft'; if not found then raise exception 'Draft payout not found'; end if; end $$;
create or replace function public.admin_mark_walker_payout_paid(p_payout_id uuid) returns void language plpgsql security definer set search_path='' as $$ begin if not private.is_admin() then raise exception 'Admin access required'; end if; update public.walker_payouts set status='paid',paid_at=now() where id=p_payout_id and status='approved'; if not found then raise exception 'Approved payout not found'; end if; end $$;
revoke all on function public.walker_request_handover(uuid,text,double precision,double precision,text) from public,anon; revoke all on function public.customer_decide_handover(uuid,boolean) from public,anon; revoke all on function public.admin_review_handover(uuid,boolean) from public,anon; revoke all on function public.report_walk_incident(uuid,text,text) from public,anon; revoke all on function public.admin_resolve_incident(uuid,text) from public,anon; revoke all on function public.admin_create_walker_payout(uuid,date,date,integer) from public,anon; revoke all on function public.admin_approve_walker_payout(uuid) from public,anon; revoke all on function public.admin_mark_walker_payout_paid(uuid) from public,anon;
grant execute on function public.walker_request_handover(uuid,text,double precision,double precision,text) to authenticated; grant execute on function public.customer_decide_handover(uuid,boolean) to authenticated; grant execute on function public.admin_review_handover(uuid,boolean) to authenticated; grant execute on function public.report_walk_incident(uuid,text,text) to authenticated; grant execute on function public.admin_resolve_incident(uuid,text) to authenticated; grant execute on function public.admin_create_walker_payout(uuid,date,date,integer) to authenticated; grant execute on function public.admin_approve_walker_payout(uuid) to authenticated; grant execute on function public.admin_mark_walker_payout_paid(uuid) to authenticated;